const path=require("path");const{execSync}=require("child_process");const fs=require("fs");const hooksDir=__dirname;const autoFormatter=require(path.join(hooksDir,"autoFormatter.js"));const buildChecker=require(path.join(hooksDir,"buildChecker.js"));const observe=require(path.join(hooksDir,"observe.js"));const agentState=require(path.join(hooksDir,"agentStateManager.js"));let outputSecretFilter;try{outputSecretFilter=require(path.join(hooksDir,"outputSecretFilter.js"))}catch(e){}const EVIDENCE_PATH=path.join(__dirname,"../gemini-bridge/.completion-evidence.json");function trackVerificationEvidence(toolName,toolInput){try{let state={buildRun:false,scssCompileRun:false,mybatisCheckRun:false,editedFileTypes:[],lastEditAt:null,lastVerifyAt:null};try{if(fs.existsSync(EVIDENCE_PATH)){state=JSON.parse(fs.readFileSync(EVIDENCE_PATH,"utf8"));if(!Array.isArray(state.editedFileTypes))state.editedFileTypes=[]}}catch(_){}if(toolName==="Bash"){const cmd=(toolInput.command||"").toString();if(/mvn\s+(clean\s+)?(compile|package|test|verify)/.test(cmd)){state.buildRun=true;state.lastVerifyAt=Date.now()}if(/sass\s|scss\s|node-sass|dart-sass/.test(cmd)){state.scssCompileRun=true;state.lastVerifyAt=Date.now()}if(/grep.*xml|mybatis/i.test(cmd)){state.mybatisCheckRun=true;state.lastVerifyAt=Date.now()}}if(toolName==="Edit"||toolName==="Write"){const filePath=(toolInput.file_path||"").toString();const ext=path.extname(filePath);const TRACKED_EXTS=[".java",".scss",".xml"];if(ext&&TRACKED_EXTS.includes(ext)&&!state.editedFileTypes.includes(ext)){state.editedFileTypes.push(ext)}if(ext&&TRACKED_EXTS.includes(ext)){state.lastEditAt=Date.now()}}const dir=path.dirname(EVIDENCE_PATH);if(!fs.existsSync(dir))fs.mkdirSync(dir,{recursive:true});fs.writeFileSync(EVIDENCE_PATH,JSON.stringify(state,null,2),"utf8")}catch(_){}}function runShellHook(scriptName,stdinData,timeoutMs=5e3){const scriptPath=path.join(hooksDir,scriptName);if(!fs.existsSync(scriptPath))return;try{const result=execSync(`bash "${scriptPath}"`,{input:JSON.stringify(stdinData),timeout:timeoutMs,encoding:"utf8",stdio:["pipe","pipe","pipe"]});if(result&&result.trim()){process.stdout.write(result)}}catch(e){process.stderr.write(`[Orchestrator] ${scriptName} error: ${e.message}\n`)}}async function orchestrate(event){const toolName=event.tool_name||event.tool||"";const toolInput=event.tool_input||{};const filePath=toolInput.file_path||"";const isEditWrite=["Edit","Write"].includes(toolName);const isBash=toolName==="Bash";const isScss=filePath.endsWith(".scss");if(isEditWrite){try{const hookEvent={tool:toolName,parameters:toolInput};await autoFormatter.onPostToolUse(hookEvent)}catch(e){process.stderr.write(`[Orchestrator] autoFormatter: ${e.message}\n`)}}if(isEditWrite){try{const context={editedFiles:filePath?[filePath]:[]};await buildChecker.onPostToolUse(context)}catch(e){process.stderr.write(`[Orchestrator] buildChecker: ${e.message}\n`)}}if(isEditWrite&&isScss){runShellHook("scssValidator.sh",event)}if(isEditWrite){runShellHook("gemini-collector.sh",event)}if(isBash&&outputSecretFilter&&outputSecretFilter.filterSecrets){try{outputSecretFilter.filterSecrets(event)}catch(e){process.stderr.write(`[Orchestrator] outputSecretFilter: ${e.message}\n`)}}try{observe.processEvent(event)}catch(e){process.stderr.write(`[Orchestrator] observe: ${e.message}\n`)}try{if(!orchestrate._callCount)orchestrate._callCount=0;orchestrate._callCount++;if(orchestrate._callCount%10===0){checkGeminiReviewsRealtime()}}catch(e){}try{if(orchestrate._callCount%50===0){agentState.cleanupStale()}}catch(e){}try{trackVerificationEvidence(toolName,toolInput)}catch(e){}}function checkGeminiReviewsRealtime(){const reviewsDir=path.join(__dirname,"../gemini-bridge/reviews");const shownFile=path.join(__dirname,"../gemini-bridge/.shown-reviews.json");if(!fs.existsSync(reviewsDir))return;let shown=[];try{if(fs.existsSync(shownFile)){shown=JSON.parse(fs.readFileSync(shownFile,"utf8"))}}catch(_){shown=[]}const reviewFiles=fs.readdirSync(reviewsDir).filter(f=>f.endsWith(".json")&&!shown.includes(f));if(reviewFiles.length===0)return;const newReviews=[];for(const f of reviewFiles){try{const data=JSON.parse(fs.readFileSync(path.join(reviewsDir,f),"utf8"));if(data.status==="completed"&&data.needsAttention){newReviews.push({name:f,data:data})}if(data.status==="completed"){shown.push(f)}}catch(_){}}try{const dir=path.dirname(shownFile);if(!fs.existsSync(dir))fs.mkdirSync(dir,{recursive:true});fs.writeFileSync(shownFile,JSON.stringify(shown,null,2),"utf8")}catch(_){}if(newReviews.length===0)return;const feedback=[``,`┌─── GEMINI REVIEW FEEDBACK (realtime) ───────────────┐`];for(const review of newReviews){const d=review.data;const issues=d.issues||[];const critical=issues.filter(x=>x.severity==="critical");const type=(d.scanType||"review").toUpperCase();feedback.push(`│ [${type}] ${review.name}`);feedback.push(`│   Issues: ${issues.length} (critical: ${critical.length})`);critical.slice(0,3).forEach(issue=>{const text=(issue.text||"").substring(0,70);feedback.push(`│   CRITICAL: ${text}`)});if(d.verdict){feedback.push(`│   Verdict: ${d.verdict}`)}}feedback.push(`│`);feedback.push(`│ Run /gemini-handoff read for full details`);feedback.push(`└────────────────────────────────────────────────────┘`);feedback.push(``);process.stderr.write(feedback.join("\n"))}if(require.main===module){let input="";process.stdin.setEncoding("utf8");process.stdin.on("data",chunk=>{input+=chunk});process.stdin.on("end",async()=>{try{const event=JSON.parse(input);await orchestrate(event);process.exit(0)}catch(e){process.stderr.write(`[Orchestrator] Parse error: ${e.message}\n`);process.exit(0)}});setTimeout(()=>{process.exit(0)},18e4)}module.exports={orchestrate:orchestrate};